		aside_post: ". ᐊᓂᒪ ᐃᐧᑎᒋᑫᐃᐧᐣ ᓇᒪᐃᐧᔭ ᐃᐧᔭᓯᐤᐃᐧᐣ ᐊᔮᔭᐤ ᑲᓇᑕ, ᐊᓂᒪ ᐅᒋ ᓇᒪᐃᐧᔭ ᓂᑦ-ᐋᐸᒋᐦᑖᓈᐣ ᑎᐯᔨᒋᑫᐃᐧᐣ ᐃᔑᓇᑲᐧᐠ. ᑭᒋ-ᐊᐧᐸᐦᑎᑖᑎᐣ ᑫᑯᐠ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐃᔑᐦᑎᐠ; ᑭᔭ ᑭᒋ-ᑎᐯᔨᒋᑫᐣ. ᐅᔮᐢᑫᐧᔪᑲᐧᐠ ᐊᔮᔮᐃᐧᓇ — ᑫᑯᐠ ᐃᐧᔭᓯᐃᐧᐣ ᑌᐯᔨᒪᐤ, ᐁᑲᐧ ᑖᓂᔅᐱᔥ ᓂᑮ-ᑎᐯᔨᒋᑫᐤ — ᐊᐧᐸᐦᑎᐣ ",
