		p1: "ᐊᓚᐱᕐᑌᐃᐧᐠ ᑮ-ᐃᔑ-ᑎᐸᐦᐊᑲᐧᐤ 87 ᐊᐢᑎᐦᑫᐃᐧᓇ. ᒥᓯᐁᐧ ᐯᔭᐠ ᐅᔥᑭᐦᐊᐤ ᐯᔭᐠ MLA ᑭᒋ-ᐃᐢᑲᐧᐃᐧᐃᐧᑲᒥᐠ. ᑭᑦ-ᐊᐢᑎᐦᑫᐃᐧᐣ ᑎᐯᔨᒋᑫᐤ ᐊᐊᐧᓂᐦᐃ ᐃᐧᐦᑎᔅ, ᑖᓂ ᐅᑌᓈᐠ ᐊᔭᓀᔥᑲᒪᑲᐧᐤ ᑭ-ᐅᑌᓈᐠ, ᐁᑲᐧ ᐊᐊᐧᓂᐦᐃ ᐃᑌᔨᐦᑕᒧᐃᐧᓇ ᑭ-MLA ᓀᐢᑖᒻ ᐯᐦᑕᒻ.",
