		p3: "ᐊᓂᒪ ᐅᐃᐧᔭᓯᐁᐧᐃᐧᐣ. ᐅᒪ ᑲᐧᔭᐢᐠ ᑮ-ᑮᐢᑲᓀᐢᑌᐤ. ᒪᒪᐃᐧᐢᑌᐃᐧᑭᒪᐠ ᓇᒪᐃᐧᔭ ᑭᑲ-ᓇᐦᐃᔓᐦᑲᐃᐧᐠ, ᐁᑲᐧ ᑮ-ᒪᔥᑭᐢᑫᔨᐦᑕᒬᐤ ᓂᔓ, ᑕᑐᑲᐃᐧᔭᐠ ᐅᑦ-ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ. ᐊᐢᐱᐦᐃᔅ MLAs ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᑮ-ᑭᔥᑲᐱᐦᐊᒻ ᐊᓂᑭ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐁᑲᐧ ᑮ-ᒪᒋᑖᐤ ᐅᑦ-ᐃᐧᔭᓯᐃᐧᐣ ᐅᔑᐦᑖᐃᐧᐣ, ᐃᔥᐱᔥ-ᐊᔭᐃᐧᐠ. ᑭᒋ-ᐃᐢᑲᐧᐃᐧᐃᐧᑲᒥᐠ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐅᒪ ᐃᔑ-ᑎᐯᔨᒪᐤ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᓇᒪᐃᐧᔭ ᐅᐦᒋᔭᐢᑭ.",
		p4: "ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐊᐢᑭᐠ ᑎᐯᔨᒋᑫᐤ ᐊᐊᐧᓂᐦᐃ ᐅᑎᐢᑫᐃᐧᐣ ᑫᑯᐠ. ᑭᑲ-ᐯᔭᑲᐧᔣᐠ ᐃᔭᔨᐃᐧᐣ ᐅᑦ-ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᓇ, ᑲᑯ ᑭᑲ-ᐊᔭᓀᔥᑲᒻ ᒥᐦᒋᑦ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇᐠ ᐊᓂᑌ ᐅᑎᐦᑫᐃᐧᐣ ᓇᒪᐃᐧᔭ ᒥᐢᑌᔨᐦᑖᑲᐧᐣ. ᑭᑲ-ᐯᔭᐠ ᐃᔥᐃᐧᐃᐧᓇ ᐯᔥᑭᔥᑖᐤ ᐁᑲᐧ ᑯᑕᑲᐠ ᓇᒪᐃᐧᔭ ᑮ-ᐅᑎᓂᑲᑌᐃᐧᓇᐠ. ᓇᒪᐃᐧᔭ ᐅᔅᑭᓇᑲᐧᐣ ᐃᔥᐱᒥᐠ; ᑎᐯᔨᒋᑲᑌᐤ ᑖᓂᑌ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐊᐢᑖᐃᐧᓇ."
