		p1: "ᐃᔥᐱ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᑮ-ᒪᔥᑭᐢᑫᔨᐦᑕᒬᐤ, ᓇᒪᐃᐧᔭ ᑮ-ᐅᔑᐦᑖᐤ ᐯᔭᐠ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᒪᔥᑭᐢᑫᔨᐦᑕᒧᐃᐧᐣ ᐊᑭᔥᑫᐠ. ᑮ-ᐅᔑᐦᑖᐤ ᓂᔓ ᒥᓯᐁᐧ, ᒬᔥᒋᐦᐃᑎᑲᐧᐤ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ. ᓂᔣᒃ ᐃᐧᔭᓯᐁᐧᐃᐧᐣ ᓀᑎ. ᐯᔭᑲᐧᔣᐠ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐊᔅᒋᔮᐸᐦᑖᐤ.",
		p2: "ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐊᔭᔭᐤ ᓂᔮᓇᐤ ᒪᒪᐃᐧᐢᑌᐃᐧᑭᒪᐠ. ᐊᓚᐱᕐᑌᐃᐧᐠ ᑭᒋ-ᑎᐯᐧᐃᐧᑭᒪᐤ ᐃᔑᓂᑲᑌᐤ ᑭᒋᔫᐠ — ᑲᐧᔭᐢᐠ-ᑫᐧᐢᑕᐱᐃᐧᐣ, ᐅᑕ Dallas K. Miller, ᑲᑮᔭᐢ Court of King’s Bench ᑎᐯᐧᐃᐧᑭᒪᐤ. ᐃᔥᑭᐊᐧᐠ ᐅᑎᐯᔨᒋᑫᐃᐧᐣ ᓂᔓ ᐃᔑᓂᑲᑌᐤ; ᐅᑎᔥᐢᑲᓂᑫᐤ ᓂᔓ ᐃᔑᓂᑲᑌᐤ.",
		p5: "ᐅᒪ ᐊᔭᔮᐱᐦᐊ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐃᔥᐱᒥᐠ ᐅᒪ ᒪᐢᑭᓯᓂᐦᐃᑲᓂᐦᐠ ᑭᒋ-ᑲᓇᐧᐊᐸᐦᑕᒫᓱᐣ. ᐊᔭᓀᔥᑲᒪᑫᐤ ᓂᔓ ᐅᔑᐦᑖᐃᐧᓇ ᐁᑲᐧ ᐊᓄᐦᒋ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ, ᒥᐢᑲᐣ ᑭᑦ-ᐊᐢᑎᐦᑫᐃᐧᐣ, ᐁᑲᐧ ᐊᐧᐸᐦᑎᐣ ᑖᓂ ᐅᑌᓈᐠ ᐯᔭᑲᐧᔣᐠ ᐊᔭᓀᔥᑲᒪᑲᐧᐤ ᑲᑯ ᐹᔅᑯᐦᐊᑲᐧᐤ.",
		p6: "MLAs ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐊᐢᐱᐦᐃᔅ ᑮ-ᑭᔥᑲᐱᐦᐊᒻ ᓂᔣᒃ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᑭᒋ-ᐅᔑᐦᑖᐠ ᐅᑦ-ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ, ᐃᔥᐱᑦ ᐯᐦᐱᔓᐦᑭᑲᑌᐠ 2026 — ᐅᒪ ᒪᐢᑭᓯᓂᐦᐃᑲᐣ ᐃᐧᔭᓯᐁᐧᐃᐧᐣ-ᑌᐧᐢᑭᐦᐱᔮᑭᐦᐃᑫᐃᐧᐣ ᐃᑕ ᑲᓇᐧᐊᐸᐦᑕᒻ. ᐅᐦᐅ ᓂᔓ ᐅᔑᐦᑖᐃᐧᓇ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑭᒋ-ᑲᐧᔭᐢᑭ-ᑎᐯᔨᒋᑫᐃᐧᐣ, ᐁᑲᐧ ᐊᓂᐦᐃ ᓂᓯᔥᑲᐢᒋᑫᐃᐧᓇ ᑭᑲ-ᐃᑎᔥᑭᓄᒻ ᑫᑯᐠ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐅᔑᐦᑖᐠ."
