		reader: "ᐊᐢᑭ ᓇᒪᐃᐧᔭ ᐃᔥᐃᐧᐃᐧ. ᑖᐱᐢᑯᐣ ᐅᒪ ᐃᔑ-ᐅᐧᔭᐢᑭᓇᐦᐃᑲᑌᐠ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐱᑯ ᐃᔑᓇᑲᐧᐣ rural ᐊᓚᐱᕐᑌᐃᐧᐠ ᐊᐃᐧᔭᓯᐤ ᐃᐢᐱᔥ ᑖᐺ ᐊᔭᔭᐤ. ᐃᔥᑲᐧᐤ ᐱᑯ ᐊᐢᑭ ᐃᔥᑲᐧᐤ ᐊᐦᐃ.",
