		author_p1: "ᑲᐧᔭᐢᐠ — ᐁᑲᐧ ᐊᓂᒪ ᑖᐺ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐃᔑᐦᑎᐠ. ᐅᔑᐦᒋᑲᑌᐤ Elections Alberta ᐅᑦ-ᐃᔑᓇᑲᐧᐃᐧᐣ ᐁᑲᐧ ᐅᑦ-ᐊᑭᐦᑌᐃᐧᓇ ᐅᐦᒋ, ᐱᑯ ᐊᓂᒪ ᐃᔑ-ᒥᐢᑌᔨᐦᑖᑲᐧᑯᐦᐠ ᑲ-ᑲᓇᐧᐊᐸᐦᑕᐦᑭᐠ: ᑖᓂᑕᐦᑐ ᐊᐊᐧᔭ ᑮ-ᐃᔥᐃᐧᐤ ᒥᓯᐁᐧ ᐃᔥᐃᐧᐃᐧᐣ-ᐊᐢᑭᐠ, ᐁᑲᐧ ᑖᓂ ᐃᔑ. ᐅᐧᔭᐢᑭᓇᐦᐃᑫᐃᐧᐣ ᐊᔭᔭᐤ ᓂᔓ ᐱᔅᑭᔥᑲᓂ ᐅᐦᒋ, ᐁᑲᐧ ᐅᑦ-ᑭᔥᑌᐧᐃᐧᐣ ᓄᐢᐱᓂᑫᐤ ᐱᒪᑎᓯᐃᐧᐣ-ᐊᑭᐦᑌᐃᐧᐣ — ᐊᓂᒪ ᐅᒋ ᐅᑌᓈᐠ ᐃᔅᑲᐧᐦᑌᐤ ᐁᑲᐧ ᐃᐧᑭᐃᐧᐣ-ᐊᐢᑭ ᐊᔮᓇᐦᑲᐧ.",
		author_p2: "ᐊᐢᑭ ᐸᐦᑭᓯᒧᑖᕽ ᐅᐦᒋ Ponoka ᐃᔅᑲᐧᐃᐧ-ᐊᑎᔭᐤ: ᓇᒪᐃᐧᔭ ᐃᔥᐃᐧᐃᐧ-ᐃᑕᐧᐃᐧᐣ, ᓇᒪᐃᐧᔭ ᐊᐊᐧᔭ ᑮ-ᒪᓯᓇᐦᐊᒬᐤ ᐱᒪᑎᓯᐃᐧᐣ ᑲᑯ ᐃᔥᐃᐧᐃᐧᐣ ᐊᓂᑌ. ᐃᔅᑲᐧᐃᐧ-ᐊᑎᔭᐤ ᐊᓂᒪ ᐅᒋ ᐊᐢᑭ ᓇᒪᐃᐧᔭ ᐃᔥᐃᐧᐃᐧ. ᐅᒪ ᐃᑌᔨᐦᑖᑲᐧᐣ ᓇᒪᐃᐧᔭ ᑭᒋ-ᐃᐧᑎᔅᑲᒪᐠ ᐊᑭᐦᑌᐃᐧᓇ, ᐱᑯ ᑭᒋ-ᐊᔭᒥᐦᑖᑲᐧ ᑖᓂ ᐃᔑ ᑮ-ᒪᓯᓇᐦᐃᑲᑌᐠ — ᐁᑲᐧ ᑭᒋ-ᓇᐦᐊᐃᐧᐦᑖᔭᐦᐠ ᐊᐦᐱᐢ ᐃᐢᐱᔥ ᑲᑭ-ᐱᐦᑐᑫᔭᐦᐠ.",
