			body: "\"Gerrymander\" — ᐃᐧᑎᒋᑫᐃᐧᐣ ᓇᒪᐃᐧᔭ ᐋᐸᒋᐦᑖᑲᐧᐤ ᐃᐢᐱ ᑭᒋᔫᐠ ᒪᒪᐃᐧᐦᑲᒪᑎᐃᐧᐣ ᓇᓂᐢᑖᐠ, ᐁᑲᐧ ᐅᒪ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᓇᒪᐃᐧᔭ ᑎᐯᔨᒋᑫᐃᐧᐣ ᐃᔑ ᐋᐸᒋᐦᑖᐤ. ᑫᑯᐠ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑲᑭ-ᐃᑌᐤ ᐊᐦᐊᐱᐢ ᐁᑲᐧ ᑖᐺᐃᐧᐣ ᐱᑯ: ᓀᐅᐧᐠ ᓂᔭᓄᐠ ᐊᐢᑭ-ᓂᓯᔥᑲᐢᒋᑫᐃᐧᓇ ᑲᑭ-ᐱᐢᑭᔥᑲᑫᐠ ᐃᑎᐱᐢᑲᐧᐢᒋᑲᐧᐤ <em>ᐊᑎᐦᑌᑫᐧᐃᐧᐣ ᐅᔑᐦᑖᐃᐧᐣ (minority proposal)</em> ᐁᑲᐧ ᓇᒪᐃᐧᔭ ᐃᑎᐱᐢᑲᐧᐢᒋᑲᐧᐤ <em>ᒥᐦᒋᑌᐃᐧᐣ ᐅᔑᐦᑖᐃᐧᐣ (majority proposal)</em>; ᓂᔮᓀᐡᐠ ᓂᓯᔥᑲᐢᒋᑫᐃᐧᐣ ᓇᐦᐃᔓᐦᑭᐢᑲᒻ ᓂᔣᒃ. ᑮᐢᐱᐣ ᐊᓂᒪ ᐃᔑᓇᑲᐧᐃᐧᐣ ᑌᐱᐸᔮᑲᐧᐣ ᑫᑯᐠ ᐊᐊᐧᔭᐠ ᐯᐦᑕᒧᐠ \"gerrymander\" ᐃᔑ, ᐊᓂᒪ ᑎᐯᔨᒋᑫᐃᐧᐣ ᐅᒪ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᐅᒪᔅᑭᓂᐦᐃᑫᐤ ᑲ-ᐊᔭᒥᐦᑖᐠ."
