			sub2_p: "ᐊᓂᒪ tipping-point — UCP ᑫᐧᐢᑕᐱᐃᐧᓇ 50/50 ᐊᐢᑎᐦᑫᐃᐧᐣ ᐃᐢᐱᐦᑌ — ᑭᒋ-ᑭᔅᑌᔨᒪᐣ ᓂᔥᑐ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ.",
			t3_col_a: "ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ",
			t3_col_b: "UCP ᑫᐧᐢᑕᐱᐃᐧᓇ 50/50 ᐃᐢᐱᐦᑌ",
