			table_col_minority: "ᐊᑎᐦᑌᑫᐧᐃᐧᐣ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ",
			table_col_direction: "ᐃᑌᐃᐧᐣ / ᐊᔭᔥᐱᔅᑕᑲᐧᐃᐧᐣ",
			table_r1_a: "ᑕᐸᐦᐃᑲᐣ ᑕᐸᐦᑌᑦ ᐊᔭᒥᐦᐁᐃᐧᓂᑲᒥᑦ-ᑮᔓᐦᐃᑫᐃᐧᐣ (70–85% Canada-ᐃᐧ ᐃᔑᓇᑲᐧᐣ)",
			table_r1_b: "80% — ᐃᔑᓇᑲᐧᐣ",
