			table_r2_a: "ᐱᒪᑎᓯᐃᐧ ᐃᑌᐃᐧᐣ (ᑭᒋ-ᑮᐢᑲᓀᐠ ᒥᔮᐸᓀᔨᐦᑕᑲᐧᐤ)",
			table_r2_b: "3,180",
			table_r2_c: "4,707 — 48% ᑭᒋ-ᑭᒋᔅᑌᔨᐦᑕᒻ",
			table_r2_d: "ᑌᐣ-ᐊᑦ-ᐅᔑᐦᑕᒥᐠ (ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑲᐃᐧ-ᑕᑭᓂᐦᐃᒋᑲᐣ ᑭᑲ-ᒪᑭᐢᑕᒫᐤ)",
			table_r3_a: "NE/central Calgary ᐱᒪᑎᓯᐃᐧ ᑲᑭᒋᔅᑌᔨᐦᑕᑲᐧᐠ ᐃᔥᐱᒪᐢ",
			table_r3_b: "2.8%",
