		november: {
			heading: "Lunty ᒪᒪᐃᐧᐢᑌᐃᐧᐣ",
			context_label: "ᑲᔅᑭᐦᑖᐃᐧᐣ",
			h_anomalous: "ᑖᓂ ᐊᔨᑕᐸᔥᐃᑲᐧᐤ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ",
			h_framework: "ᒪᒪᐃᐧᐢᑌᐃᐧᐣ-ᑮᐢᑲᓇᐦᑌᐃᐧᐣ ᐃᔑ-ᑲᐧᔭᐢᑭᐦᒋᑫᐃᐧᐣ",
			framework_p1: "§3 <em>Charter of Rights and Freedoms</em> — \"ᒥᑕᑐ ᑲᓇᑕᐃᐧᐤ ᑭᑦ-ᑌᐯᔨᒋᑫᐤ ᑭᒋ-ᐊᔭᒥᐦᐁᐢᑕᒫᐤ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᑲᒥᑯᐦᐠ\" — Supreme Court of Canada ᑮ-ᐃᑌᔨᐦᑕᒻ ᓇᒪᐃᐧᔭ ᒥᑐ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ-ᑎᐸᔭᐢᑎᑫᐃᐧᐣ ᒥᑐ, ᐁᑲᐧ <em>ᑎᐯᔨᒋᑫᐃᐧᐠ ᐃᔑ-ᒥᓯᓀᐦᐃᑫᐃᐧᐣ</em>. ᑭᒋ-ᐃᑌᔨᐦᑕᑲᐧᐤ ᑮᐢᑯᑕᑲᐣ: <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158, McLachlin J. ᑲᑮ-ᑎᐸᐦᐃᑫᐣ §3 ᐅᒋ-ᐃᑌᐃᐧᐣ \"ᓇᒪᐃᐧᔭ ᒥᑕᑦ-ᐃᑐᑫᐃᐧᐣ ᒥᑐ, ᒉ-ᑎᐯᔨᒋᑫᐃᐧᐠ ᐃᔑ-ᒥᓯᓀᐦᐃᑫᐃᐧᐣ.\" ᐃᔥᐱᒪᐢ ᒥᑕᑦ ᐊᐢᑭᑌᐦᐃᑲᐣ; ᐊᔅᒋᔮᐸᐦᐃᑌᐃᐧᓇ ᑲᑮᐢᑯᑕᑭᐣ ᐃᐧᒋᐦᐃᐁᐧᐃᐧ-ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ, ᑲᑮᐢᑯᑕᑭᐣ ᐊᐢᑭ, ᐊᑕᒥᐦᐅᐃᐧᐣ, ᑲᑯ ᑲᑮᐢᑯᑕᑭᐣ ᑲᑯᔑᓂᑫᐃᐧ-ᑎᐯᔨᒋᑫᐃᐧᐣ.",
			framework_p3: "ᒪᐢᑭᓯᓂᐦᐃᑫᐃᐧᐣ ᑲᑮᐢᑯᑕᒥᐠ ᑭᒋᔅᑌᔨᐦᑕᒻ ᐯᔭᑯ ᐃᑌᔭᐠ. Alberta <em>Electoral Boundaries Commission Act</em> ᓇᒪᐃᐧᔭ ᑌᐸᐃᐧᐢᑕᒪᑫᐤ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑭᒋ-ᐃᔑᓇᑲᐧᐠ ᐯᔭᐠ-ᑲ-ᑲᐧᔭᐢᑭᐦᒋᑫᐠ ᑭᒋ-ᑮᔥᑭᔥᑌᐣ, ᑲᑮ-ᐃᑌᔨᐦᑕᑲᐧᐤ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑭᒋ-ᑮᔥᑭᔥᑌᐠ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑭᒋ-ᐱᑐᑕᑫᐃᐧᐠ. §3 ᑭᒋ-ᑲᓇᐧᐊᐸᐦᑕᒥᑫᐃᐧᐣ ᑎᐯᔨᒋᑫᐃᐧᐠ ᐃᔑ-ᒥᓯᓀᐦᐃᑫᐃᐧᐣ ᑲᑮ-ᐊᑦ-ᑕᐱᓇᒪᑭᓀ.",
			h_quebec: "Quebec ᑲᔅᑭᐦᑌᔨᐦᑕᑲᐧᐤ",
			quebec_p1: "Quebec ᑲᑮ-ᐊᔨᑕᐸᔥᐃᑲᐧᐠ Alberta ᑲᑮ-ᐃᔑᐃᐧᐣ ᑭᒋ-ᑲᓇᐧᐊᐸᐦᑕᒫᐣ. Quebec Commission de la représentation électorale (CRE) ᐊᑯᐦᑲᒥᑲᐃᐧ, ᑲᔅᑭᐦᐅᐃᐧ ᑲᔅᑭᐦᑖᐃᐧᐣ ᑕᑲᐦᐃᑲᐣ — ᓇᒪᐃᐧᔭ ᐯᔭᑯ-ᑲᔅᑭᐦᑖᐃᐧᐣ. CRE ᑭᒋᔅᑌᔨᒪᐤ ᐁᑲᐧ ᓇᒪᐃᐧᔭ ᐊᐃᐧᔭ ᑭᑲ-ᑭᔥᑲᐱᐦᐊᒻ. Quebec <em>Loi électorale</em> ᑲᔅᑭᐦᑖᐃᐧᓂᐦᐠ, CRE ᐃᐧᓚᐤ ᐅᔑᐦᑖᐤ ᐃᔥᑫᐧᔮᐤ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ: National Assembly ᐊᔭᒥᐦᑖᐤ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐅᑦ-ᐊᒋᒨᐃᐧᐣ ᐁᑲᐧ ᓇᐦᐃᔭᐤ ᐱᑭᐢᑫᐧᐃᐧᓇ, ᒪᑲ ᓇᒪᐃᐧᔭ ᑌᐯᔨᒋᑫᐤ ᑭᒋ-ᐅᑎᓂᑲᑌᐠ ᑲᑯ ᑭᒋ-ᑲᔥᑭᐦᐃᑌᐠ — ᒥᑖᑐ ᑮᔑᑲᐤ ᐃᔑ ᐊᓂᒪ ᐊᔭᒥᐦᐃᑐᐃᐧᐣ ᐅᐦᒋ, ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐊᐢᑌᐤ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ, Gazette officielle ᐃᑕ ᑲᑮ-ᒪᐢᑭᓯᓂᐦᐊᑲᐧᐠ. ᐱᑯ ᑲᔭᔅᐱᔅᑕᑲᐧᐃᐧᐣ ᓇᒪᐃᐧᔭ ᑭᑲ-ᒥᐢᑲᒫᐤ, ᒥᑭ-ᑲᔭᔅᐱᔅᑕᑲᐧᐃᐧᐣ ᑲᑮ-ᒪᐢᑭᓯᓂᐦᐃᑲᑌᐠ ᑭᒋ-ᑲᔥᑭᐦᐃᑌᐠ, ᑭᑦ-ᐃᔑ-ᑭᒋᔅᑌᔨᐦᑕᑲᐧᐤ; ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐃᔑ, ᐯᔭᐠ-ᑲ-ᑲᐧᔭᐢᑭᐦᒋᑫᐠ ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐃᔥᑫᐧᔮᐤ ᐃᑌᐤ.",
			closing: "ᑲᔅᑭᐦᐅᐃᐧ ᐃᔑ-ᑲᐧᔭᐢᑭᐦᒋᑫᐃᐧᐣ ᑕᑐ ᓂᓯᔥᑲᐢᒋᑫᐃᐧᓇ ᑭᑲ-ᐊᐸᒋᐦᑕᐣ Lunty ᒪᐢᑭᓯᓂᐦᐃᑫᐃᐧᐣ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᑲᑦ-ᐱᑕᒪᐃᐧᑌᐠ. ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐁᑲᐧ ᑲᑮ-ᐊᑕᐧᑌᐠ ᐅᑕ ᐊᑯᑦ ᑲᑭ-ᒥᑐᓀᔨᒋᑲᓂᐦᐠ; ᐃᔑ-ᑲᐧᔭᐢᑭᐦᒋᑫᐃᐧᐣ ᓇᒪᐃᐧᔭ ᑲᐊᐧᔭᐢᑭᐦᒋᑫᐤ."
		},
