				body: "ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐅᓂᑲᓂᔥᑫᐤ ᓇᒪᐃᐧᔭ ᐅᒪ ᑮ-ᒪᐢᑭᓯᓂᐦᐃᑲᓂᐦᑖᐤ — ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᐅᑦ-ᐊᑭᐦᑌᐃᐧᐣ ᐃᔑ. ᒥᓯᐁᐧ Calgary ᑮᐁᐧᑎᓄᑲᐧᐠ ᐁᑲᐧ ᓵᑲᐢᑌᑲᐧᐠ (ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᐅᑦ-\"Zone A,\" ᑮᐁᐧᑎᓄᑲᐧᐠ ᐁᑲᐧ ᓵᑲᐢᑌᑲᐧᐠ Bow River ᐅᐦᒋ), ᐊᑎᐦᑌᑫᐧᐃᐧᐣ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐊᐦᐱᐢ 11.5% ᑭᒋᔥᑖᐃᐧᓇ ᐃᐢᐱᐦᑌ ᐊᐢᑭ-ᒪᓂᑐᐦᑭ ᐋᐱᐦᑕᐃᐧᐢᑌᐤ, ᐊᐢᐱᔥ 2.8% ᒥᐦᒋᑌᐃᐧᐣ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐃᔑ. ᒪᒪᐃᐧᔭᐢᑲᓂᐢᑲᐢ ᐃᑌᔭᐠ ᐯᔭᐠ ᐱᔅᑭᔥᑲᓂ ᐅᑦ-ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᓇ ᐊᔮᐢᑫᐧᔭᔅᑲᒻ ᐊᐢᐱᐦᐃᔅ ᐊᐱᐢ ᐃᔥᐱᐦᑌᐠ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇᐦᐠ, ᐁᑲᐧ ᒥᓯᐁᐧ ᐅᑦ-ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᓇ ᐊᐱᐢ ᑲᑎᔥᑖᐤ ᐊᐦᑭ; Zone A NDP-ᑲᐧᑫᒋᐦᐃᑎᐃᐧᐣ ᐊᔭᔭᐤ, ᐁᑲᐧ 13 ᐅᐦᒋ ᐅᑦ-17 ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ NDP ᑮ-ᑮᔥᑭᔥᑌᐤ 2023. ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑎᐯᔨᒋᑫᐤ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐊᔭᔥᐱᔅᑫᐧᐃᐧᐣ, ᓇᒪᐃᐧᔭ ᒪᒋᐦᑖᐃᐧᐣ. (ᑲᔅᑭᐦᐅᐃᐧ §5.3.1.)"
